/* Tampilan login baru MathQuest: hanya mengubah TAMPILAN. Sistem login (masuk.js dll) tidak disentuh. */
(function () {
  var IMG = 'data:image/png;base64,';
  var css = [
    'body.mq-login{--p:#2f5bd8;--p2:#ffc531;background:radial-gradient(900px 600px at 25% 40%,#e6f1ff,transparent 70%),radial-gradient(700px 500px at 85% 90%,#fff6d6,transparent 70%),#e6f1ff;overflow-x:hidden}',
    ':root[data-theme="dark"] body.mq-login{background:radial-gradient(900px 600px at 25% 40%,#1b2c66,transparent 70%),#0f1c45}',
    'body.mq-login #app.mq-grid{display:grid;grid-template-columns:1fr auto;align-items:center;gap:32px;max-width:1180px;min-height:100vh;padding:24px 32px}',
    '#app.mq-grid>*:not(.mq-stage){grid-column:2}',
    '.mq-stage{grid-column:1;grid-row:1;position:relative;display:flex;justify-content:center}',
    '.mq-stage img{width:min(620px,100%);height:auto;display:block;animation:mqbob 4.5s ease-in-out infinite;filter:drop-shadow(0 18px 24px rgba(20,39,94,.18))}',
    '@keyframes mqbob{50%{transform:translateY(-10px)}}',
    '.mq-sym{position:absolute;font:800 34px "Baloo 2",sans-serif;opacity:.55;animation:mqfloat 6s ease-in-out infinite}',
    '.mq-s1{left:2%;top:12%;color:#ffc531}.mq-s2{right:4%;top:6%;color:#2f5bd8;animation-delay:-2s}.mq-s3{left:6%;bottom:22%;color:#2fa36b;animation-delay:-4s}.mq-s4{right:2%;bottom:30%;color:#7a63e0;animation-delay:-1s}',
    '@keyframes mqfloat{50%{transform:translateY(-14px) rotate(8deg)}}',
    'body.mq-login #app .mq-box{width:300px;max-width:100%;margin:0;padding:18px;border-radius:18px;box-shadow:0 14px 34px rgba(20,39,94,.16)}',
    'body.mq-login .mq-box h1{font-size:1.45rem;line-height:1.1}',
    'body.mq-login .mq-box label{font-size:.8rem;margin:8px 0 3px}',
    'body.mq-login .mq-box input{padding:9px 11px;font-size:.9rem;border-radius:10px}',
    'body.mq-login .mq-box .tabs{margin:10px 0}',
    'body.mq-login .mq-box .tabs button,body.mq-login .mq-box .btn{padding:8px 12px;font-size:.9rem;border-radius:10px}',
    'body.mq-login .mq-box .btn:not(.alt){background:#ffc531;border-color:#ffc531;color:#14275e;box-shadow:0 3px 0 #d99a00}',
    'body.mq-login .mq-box .tabs .btn:not(.alt){background:#2f5bd8;border-color:#2f5bd8;color:#fff;box-shadow:none}',
    '@media (max-width:820px){body.mq-login #app.mq-grid{grid-template-columns:1fr;justify-items:center;align-content:start;gap:12px;padding:16px}#app.mq-grid>*:not(.mq-stage),.mq-stage{grid-column:1}.mq-stage img{width:min(300px,78%)}.mq-sym{font-size:26px}body.mq-login #app .mq-box{width:min(340px,100%)}}',
    '@media (prefers-reduced-motion:reduce){.mq-stage img,.mq-sym{animation:none}}'
  ].join('\n');
  var st = document.createElement('style'); st.textContent = css; document.head.appendChild(st);

  var app = document.getElementById('app');
  if (!app) return;

  function makeStage() {
    var s = document.createElement('section');
    s.className = 'mq-stage';
    s.setAttribute('aria-label', 'Maskot MathQuest');
    s.innerHTML = '<span class="mq-sym mq-s1" aria-hidden="true">+</span><span class="mq-sym mq-s2" aria-hidden="true">\u00d7</span><span class="mq-sym mq-s3" aria-hidden="true">\u2212</span><span class="mq-sym mq-s4" aria-hidden="true">\u00f7</span><img alt="MathQuest - Belajar Matematika, Raih Masa Depan, Kelas 8" src="' + IMG + '">';
    return s;
  }

  function sync() {
    var pw = app.querySelector('input[type=password]');
    var login = pw && !app.querySelector('nav');
    if (login) {
      document.body.classList.add('mq-login');
      app.classList.add('mq-grid');
      var box = pw.closest('.auth') || pw.closest('.card') || pw.closest('form');
      if (box) box.classList.add('mq-box');
      if (!app.querySelector('.mq-stage')) app.insertBefore(makeStage(), app.firstChild);
    } else {
      document.body.classList.remove('mq-login');
      app.classList.remove('mq-grid');
      var old = app.querySelector('.mq-stage');
      if (old) old.remove();
    }
  }
  new MutationObserver(sync).observe(app, { childList: true, subtree: true });
  sync();
})();
